using System.Text.Json;
using EvalLab.Api.Evaluation;

namespace EvalLab.Api.Tests.Evaluation;

/// <summary>
/// Compares MetricsCalculator with reference values generated by scikit-learn.
/// Regenerate the fixture with: uv run scripts/generate_metrics_fixtures.py
/// </summary>
public sealed class MetricsCalculatorTests
{
    private const double Tolerance = 1e-9;

    private static readonly string[] Labels = ["technical_support", "billing", "general_inquiry", "account_management"];

    private static readonly MetricsFixture Fixture = LoadFixture();

    public static TheoryData<string> CaseNames => new(Fixture.Cases.Select(c => c.Name));

    [Fact]
    public void Fixture_UsesTheSameLabelSet()
    {
        Assert.Equal(Labels, Fixture.Labels);
    }

    [Theory]
    [MemberData(nameof(CaseNames))]
    public void Calculate_MatchesReferenceValues(string caseName)
    {
        var expected = Fixture.Cases.Single(c => c.Name == caseName);
        var pairs = expected.Expected.Zip(expected.Predicted).ToList();

        var metrics = MetricsCalculator.Calculate(pairs, Labels);

        Assert.Equal(expected.Accuracy, metrics.Accuracy, Tolerance);
        Assert.Equal(expected.InvalidCount, metrics.InvalidCount);

        Assert.Equal(expected.PerClass.Select(c => c.Label), metrics.PerClass.Select(c => c.Label));
        foreach (var (expectedClass, actualClass) in expected.PerClass.Zip(metrics.PerClass))
        {
            Assert.Equal(expectedClass.Precision, actualClass.Precision, Tolerance);
            Assert.Equal(expectedClass.Recall, actualClass.Recall, Tolerance);
            Assert.Equal(expectedClass.F1, actualClass.F1, Tolerance);
            Assert.Equal(expectedClass.Support, actualClass.Support);
        }

        Assert.Equal(expected.Macro.Precision, metrics.MacroPrecision, Tolerance);
        Assert.Equal(expected.Macro.Recall, metrics.MacroRecall, Tolerance);
        Assert.Equal(expected.Macro.F1, metrics.MacroF1, Tolerance);
        Assert.Equal(expected.Weighted.Precision, metrics.WeightedPrecision, Tolerance);
        Assert.Equal(expected.Weighted.Recall, metrics.WeightedRecall, Tolerance);
        Assert.Equal(expected.Weighted.F1, metrics.WeightedF1, Tolerance);

        Assert.Equal(expected.ConfusionMatrix.Rows, metrics.ConfusionMatrix.Rows);
        Assert.Equal(expected.ConfusionMatrix.Columns, metrics.ConfusionMatrix.Columns);
        Assert.Equal(expected.ConfusionMatrix.Counts.Count, metrics.ConfusionMatrix.Counts.Count);
        foreach (var (expectedRow, actualRow) in expected.ConfusionMatrix.Counts.Zip(metrics.ConfusionMatrix.Counts))
        {
            Assert.Equal(expectedRow, actualRow);
        }
    }

    [Fact]
    public void Calculate_EmptyInput_ThrowsArgumentException()
    {
        Assert.Throws<ArgumentException>(() => MetricsCalculator.Calculate([], Labels));
    }

    [Fact]
    public void Calculate_ExpectedLabelOutsideLabelSet_ThrowsArgumentException()
    {
        (string, string)[] pairs = [("billing", "billing"), ("sales", "billing")];

        Assert.Throws<ArgumentException>(() => MetricsCalculator.Calculate(pairs, Labels));
    }

    [Fact]
    public void Calculate_PredictedLabelNeitherCategoryNorInvalid_ThrowsArgumentException()
    {
        (string, string)[] pairs = [("billing", "billing"), ("billing", "sales")];

        Assert.Throws<ArgumentException>(() => MetricsCalculator.Calculate(pairs, Labels));
    }

    private static MetricsFixture LoadFixture()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "Evaluation", "Fixtures", "metrics-cases.json");
        var options = new JsonSerializerOptions
        {
            PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower,
            RespectRequiredConstructorParameters = true,
        };
        return JsonSerializer.Deserialize<MetricsFixture>(File.ReadAllText(path), options)
            ?? throw new InvalidOperationException($"Could not read {path}.");
    }

    private sealed record MetricsFixture(IReadOnlyList<string> Labels, IReadOnlyList<MetricsCase> Cases);

    private sealed record MetricsCase(
        string Name,
        IReadOnlyList<string> Expected,
        IReadOnlyList<string> Predicted,
        double Accuracy,
        int InvalidCount,
        IReadOnlyList<ClassCase> PerClass,
        AveragedCase Macro,
        AveragedCase Weighted,
        MatrixCase ConfusionMatrix);

    private sealed record ClassCase(string Label, double Precision, double Recall, double F1, int Support);

    private sealed record AveragedCase(double Precision, double Recall, double F1);

    private sealed record MatrixCase(
        IReadOnlyList<string> Rows,
        IReadOnlyList<string> Columns,
        IReadOnlyList<IReadOnlyList<int>> Counts);
}
